#!/usr/bin/env bash

# =============================================================================
# Run Script — starts 2 servers concurrently with colored prefixed logs.
# Generated by the "Add Run Script" skill.
# =============================================================================

set -e

# Resolve script root directory for robust relative paths
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# ---------------------------------------------------------------------------
# Colors
# ---------------------------------------------------------------------------
# Cycle: blue, green, cyan, magenta, yellow, red
COLORS=(
    $'\033[0;34m'  # blue
    $'\033[0;32m'  # green
    $'\033[0;36m'  # cyan
    $'\033[0;35m'  # magenta
    $'\033[0;33m'  # yellow
    $'\033[0;31m'  # red
)
RED=$'\033[0;31m'
YELLOW=$'\033[0;33m'
NC=$'\033[0m'

# ---------------------------------------------------------------------------
# Server Configuration
# ---------------------------------------------------------------------------
# Arrays — parallel indexed. Modify these to add/remove servers.
LABELS=("frontend" "backend")
DIRS=("$SCRIPT_DIR" "$SCRIPT_DIR/server")
CMDS=("npm run dev" "npm run dev")
PKG_MANAGER="npm"

PIDS=()
LINT=0
PRETTIFY=0

# ---------------------------------------------------------------------------
# Argument Parsing
# ---------------------------------------------------------------------------
usage() {
    echo "Usage: $0 [options]"
    echo "Options:"
    echo "  -l, --lint       Run linting across all directories before starting"
    echo "  -p, --prettify   Run Prettier formatting across all directories before starting"
    echo "  -h, --help       Show this help message"
    exit 0
}

while [[ "$#" -gt 0 ]]; do
    case $1 in
        -l|--lint)     LINT=1 ;;
        -p|--prettify) PRETTIFY=1 ;;
        -h|--help)     usage ;;
        *)
            echo -e "${RED}Unknown parameter: $1${NC}"
            echo "Use -h or --help for usage."
            exit 1
            ;;
    esac
    shift
done

# ---------------------------------------------------------------------------
# Helper — run a command in a directory, prefixing every output line
# ---------------------------------------------------------------------------
run_with_prefix() {
    local prefix="$1"
    local dir="$2"
    local cmd="$3"

    if [[ ! -d "$dir" ]]; then
        echo -e "${RED}Directory '${dir}' not found!${NC}"
        return 1
    fi

    (
        cd "$dir"
        FORCE_COLOR=1 eval "$cmd" 2>&1 | while IFS= read -r line || [[ -n "$line" ]]; do
            printf "%s %s\n" "$prefix" "$line"
        done
    )
}

# ---------------------------------------------------------------------------
# Helper — detect if a package.json script exists
# ---------------------------------------------------------------------------
has_npm_script() {
    local dir="$1"
    local script="$2"
    [[ -f "$dir/package.json" ]] && grep -q "\"$script\"" "$dir/package.json"
}

# ---------------------------------------------------------------------------
# Lint
# ---------------------------------------------------------------------------
run_lint() {
    echo -e "${YELLOW}==> Starting linting...${NC}"
    for i in "${!LABELS[@]}"; do
        local label="${LABELS[$i]}"
        local dir="${DIRS[$i]}"
        local color="${COLORS[$((i % ${#COLORS[@]}))]}"

        echo -e "${color}[$label]${NC} Running linter..."
        (
            cd "$dir"
            if has_npm_script "$dir" "lint"; then
                $PKG_MANAGER run lint
            elif [[ -f "package.json" ]]; then
                npx eslint . 2>/dev/null || echo -e "${YELLOW}[$label] No eslint config found or linting failed.${NC}"
            else
                echo -e "${YELLOW}[$label] No linter configured — skipping.${NC}"
            fi
        )
    done
    echo -e "${YELLOW}==> Linting completed.${NC}\n"
}

# ---------------------------------------------------------------------------
# Prettify
# ---------------------------------------------------------------------------
run_prettify() {
    echo -e "${YELLOW}==> Starting Prettier formatting...${NC}"
    for i in "${!LABELS[@]}"; do
        local label="${LABELS[$i]}"
        local dir="${DIRS[$i]}"
        local color="${COLORS[$((i % ${#COLORS[@]}))]}"

        echo -e "${color}[$label]${NC} Running Prettier..."
        (
            cd "$dir"
            if has_npm_script "$dir" "format"; then
                $PKG_MANAGER run format
            elif has_npm_script "$dir" "prettier"; then
                $PKG_MANAGER run prettier
            elif [[ -f "package.json" ]]; then
                npx prettier --write .
            else
                echo -e "${YELLOW}[$label] No formatter configured — skipping.${NC}"
            fi
        )
    done
    echo -e "${YELLOW}==> Prettier formatting completed.${NC}\n"
}

# ---------------------------------------------------------------------------
# Pre-run phases (sequential)
# ---------------------------------------------------------------------------
[[ $LINT -eq 1 ]] && run_lint
[[ $PRETTIFY -eq 1 ]] && run_prettify

# ---------------------------------------------------------------------------
# Concurrent server startup
# ---------------------------------------------------------------------------
set +e

echo -e "${YELLOW}==> Starting ${#LABELS[@]} servers concurrently...${NC}"
echo -e "${YELLOW}Press Ctrl+C to stop all servers${NC}\n"

for i in "${!LABELS[@]}"; do
    color="${COLORS[$((i % ${#COLORS[@]}))]}"
    prefix="${color}[${LABELS[$i]}]${NC}"
    run_with_prefix "$prefix" "${DIRS[$i]}" "${CMDS[$i]}" &
    PIDS+=($!)
done

# ---------------------------------------------------------------------------
# Cleanup
# ---------------------------------------------------------------------------
cleanup() {
    trap - SIGINT SIGTERM EXIT
    echo -e "\n${YELLOW}==> Shutting down servers...${NC}"
    for pid in "${PIDS[@]}"; do
        pkill -P "$pid" 2>/dev/null || true
        kill "$pid" 2>/dev/null || true
    done
    for pid in "${PIDS[@]}"; do
        wait "$pid" 2>/dev/null || true
    done
    echo -e "${YELLOW}==> All servers stopped.${NC}"
    exit 0
}

trap cleanup SIGINT SIGTERM EXIT

# Wait for any process to exit — if one crashes, cleanup triggers
wait -n
